/* Pixel Cinema Seat Picker styles */
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --seat-free: #0f3460;
  --seat-taken: #533483;
  --seat-selected: #e94560;
  --text: #eaeaea;
  --accent: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px 16px;
  max-width: 520px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  margin-bottom: 4px;
  color: var(--accent);
}

.subtitle {
  font-size: 1rem;
  opacity: 0.8;
  margin-bottom: 20px;
}

.screen {
  background: linear-gradient(to bottom, #ffffff33, transparent);
  color: var(--text);
  font-size: 0.9rem;
  letter-spacing: 4px;
  padding: 8px;
  margin-bottom: 20px;
  border-radius: 4px;
}

.seat-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 6px;
  margin-bottom: 24px;
}

.seat {
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: 6px;
  background: var(--seat-free);
  color: var(--text);
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

.seat:hover:not(:disabled) {
  background: #1a4a7a;
}

.seat:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.seat:active:not(:disabled) {
  transform: scale(0.92);
}

.seat.taken {
  background: var(--seat-taken);
  cursor: not-allowed;
  opacity: 0.6;
}

.seat.selected {
  background: var(--seat-selected);
  color: #fff;
}

.seat.selected:hover {
  background: #f05a72;
}

.summary {
  font-size: 1.1rem;
  line-height: 1.8;
}

.label {
  font-weight: 700;
  color: var(--accent);
}

#selected-seats {
  word-break: break-word;
}

@media (max-width: 400px) {
  .seat {
    font-size: 0.65rem;
  }
  .card {
    padding: 16px 8px;
  }
}

// Pixel Cinema Seat Picker
(function () {
  'use strict';

  const ROWS = ['A', 'B', 'C', 'D', 'E'];
  const COLS = 8;
  const PRICE_PER_SEAT = 9;

  // Predefined taken seats (row letter + seat number)
  const TAKEN = new Set(['A3', 'A4', 'B6', 'C2', 'C7', 'D5', 'E1', 'E8']);

  const grid = document.getElementById('seat-grid');
  const selectedDisplay = document.getElementById('selected-seats');
  const totalDisplay = document.getElementById('total-price');

  const selected = new Set();

  // Build seat buttons
  ROWS.forEach(row => {
    for (let col = 1; col <= COLS; col++) {
      const id = row + col;
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'seat';
      btn.textContent = col;
      btn.dataset.id = id;
      btn.setAttribute('aria-label', `Seat ${id}`);
      btn.setAttribute('role', 'gridcell');

      if (TAKEN.has(id)) {
        btn.classList.add('taken');
        btn.disabled = true;
        btn.setAttribute('aria-disabled', 'true');
      } else {
        btn.addEventListener('click', () => toggleSeat(id, btn));
      }

      grid.appendChild(btn);
    }
  });

  function toggleSeat(id, btn) {
    if (selected.has(id)) {
      selected.delete(id);
      btn.classList.remove('selected');
      btn.setAttribute('aria-pressed', 'false');
    } else {
      selected.add(id);
      btn.classList.add('selected');
      btn.setAttribute('aria-pressed', 'true');
    }
    updateSummary();
  }

  function updateSummary() {
    const sorted = Array.from(selected).sort((a, b) => {
      const rowA = a[0], rowB = b[0];
      if (rowA !== rowB) return rowA.localeCompare(rowB);
      return parseInt(a.slice(1), 10) - parseInt(b.slice(1), 10);
    });

    selectedDisplay.textContent = sorted.length ? sorted.join(', ') : 'None';
    totalDisplay.textContent = '$' + (sorted.length * PRICE_PER_SEAT);
  }
})();
